import{_ as a,o as s,c as e,a3 as i}from"./chunks/framework.6_aCw6yF.js";const u=JSON.parse('{"title":"框架与中间件","description":"Spring、Spring Boot、Spring Security、MyBatis、JPA、日志与 Tomcat。","frontmatter":{"title":"框架与中间件","description":"Spring、Spring Boot、Spring Security、MyBatis、JPA、日志与 Tomcat。","date":"2026-11-20T00:00:00.000Z","category":"匠心造物","subCategory":"Java 面试","tags":["面试","Spring","Spring Boot"],"author":"闲生"},"headers":[],"relativePath":"posts/create/interview/frameworks.md","filePath":"posts/create/interview/frameworks.md"}'),p={name:"posts/create/interview/frameworks.md"};function t(l,n,o,r,c,g){return s(),e("div",null,[...n[0]||(n[0]=[i(`<h1 id="框架与中间件" tabindex="-1">框架与中间件 <a class="header-anchor" href="#框架与中间件" aria-label="Permalink to &quot;框架与中间件&quot;">​</a></h1><blockquote><p>开发框架相关</p></blockquote><h2 id="spring" tabindex="-1">Spring <a class="header-anchor" href="#spring" aria-label="Permalink to &quot;Spring&quot;">​</a></h2><h3 id="什么是spring框架" tabindex="-1">什么是Spring框架？ <a class="header-anchor" href="#什么是spring框架" aria-label="Permalink to &quot;什么是Spring框架？&quot;">​</a></h3><p>Spring是一种轻量级框架，旨在提高开发人员的开发效率以及系统的可维护性。</p><p>我们一般说的Spring框架就是Spring Framework，它是很多模块的集合，使用这些模块可以很方便地协助我们进行开发。这些模块是核心容器、数据访问/集成、Web、AOP（面向切面编程）、工具、消息和测试模块。比如Core Container中的Core组件是Spring所有组件的核心，Beans组件和Context组件是实现IOC和DI的基础，AOP组件用来实现面向切面编程。</p><p>Spring官网列出的Spring的6个特征：</p><ul><li>核心技术：依赖注入（DI），AOP，事件（Events），资源，i18n，验证，数据绑定，类型转换，SpEL。</li><li>测试：模拟对象，TestContext框架，Spring MVC测试，WebTestClient。</li><li>数据访问：事务，DAO支持，JDBC，ORM，编组XML。</li><li>Web支持：Spring MVC和Spring WebFlux Web框架。</li><li>集成：远程处理，JMS，JCA，JMX，电子邮件，任务，调度，缓存。</li><li>语言：Kotlin，Groovy，动态语言。</li></ul><h3 id="列举一些重要的spring模块" tabindex="-1">列举一些重要的Spring模块？ <a class="header-anchor" href="#列举一些重要的spring模块" aria-label="Permalink to &quot;列举一些重要的Spring模块？&quot;">​</a></h3><p>下图对应的是Spring 4.x的版本，目前最新的5.x版本中Web模块的Portlet组件已经被废弃掉，同时增加了用于异步响应式处理的WebFlux组件。</p><ul><li>Spring Core：基础，可以说Spring其他所有的功能都依赖于该类库。主要提供IOC和DI功能。</li><li>Spring Aspects：该模块为与AspectJ的集成提供支持。</li><li>Spring AOP：提供面向切面的编程实现。</li><li>Spring JDBC：Java数据库连接。</li><li>Spring JMS：Java消息服务。</li><li>Spring ORM：用于支持Hibernate等ORM工具。</li><li>Spring Web：为创建Web应用程序提供支持。</li><li>Spring Test：提供了对JUnit和TestNG测试的支持。</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/9d5e0da02e.png" alt=""></p><h3 id="什么是ioc-如何实现的" tabindex="-1">什么是IOC? 如何实现的？ <a class="header-anchor" href="#什么是ioc-如何实现的" aria-label="Permalink to &quot;什么是IOC? 如何实现的？&quot;">​</a></h3><p>IOC（Inversion Of Controll，控制反转）是一种设计思想，就是将原本在程序中手动创建对象的控制权，交给IOC容器来管理，并由IOC容器完成对象的注入。这样可以很大程度上简化应用的开发，把应用从复杂的依赖关系中解放出来。IOC容器就像是一个工厂一样，当我们需要创建一个对象的时候，只需要配置好配置文件/注解即可，完全不用考虑对象是如何被创建出来的。</p><p>Spring 中的 IoC 的实现原理就是工厂模式加反射机制。</p><p>示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>interface Fruit {</span></span>
<span class="line"><span>     public abstract void eat();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>class Apple implements Fruit {</span></span>
<span class="line"><span>    public void eat(){</span></span>
<span class="line"><span>        System.out.println(&quot;Apple&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>class Orange implements Fruit {</span></span>
<span class="line"><span>    public void eat(){</span></span>
<span class="line"><span>        System.out.println(&quot;Orange&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>class Factory {</span></span>
<span class="line"><span>    public static Fruit getInstance(String ClassName) {</span></span>
<span class="line"><span>        Fruit f=null;</span></span>
<span class="line"><span>        try {</span></span>
<span class="line"><span>            f=(Fruit)Class.forName(ClassName).newInstance();</span></span>
<span class="line"><span>        } catch (Exception e) {</span></span>
<span class="line"><span>            e.printStackTrace();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        return f;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>class Client {</span></span>
<span class="line"><span>    public static void main(String[] a) {</span></span>
<span class="line"><span>        Fruit f=Factory.getInstance(&quot;io.github.dunwu.spring.Apple&quot;);</span></span>
<span class="line"><span>        if(f!=null){</span></span>
<span class="line"><span>            f.eat();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="什么是aop-有哪些aop的概念" tabindex="-1">什么是AOP? 有哪些AOP的概念？ <a class="header-anchor" href="#什么是aop-有哪些aop的概念" aria-label="Permalink to &quot;什么是AOP? 有哪些AOP的概念？&quot;">​</a></h3><p>AOP（Aspect-Oriented Programming，面向切面编程）能够将那些与业务无关，却为业务模块所共同调用的逻辑或责任（例如事务处理、日志管理、权限控制等）封装起来，便于减少系统的重复代码，降低模块间的耦合度，并有利于未来的可扩展性和可维护性。</p><p>Spring AOP是基于动态代理的，如果要代理的对象实现了某个接口，那么Spring AOP就会使用JDK动态代理去创建代理对象；而对于没有实现接口的对象，就无法使用JDK动态代理，转而使用CGlib动态代理生成一个被代理对象的子类来作为代理。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/c0f791f909.png" alt=""></p><p>当然也可以使用AspectJ，Spring AOP中已经集成了AspectJ，AspectJ应该算得上是Java生态系统中最完整的AOP框架了。使用AOP之后我们可以把一些通用功能抽象出来，在需要用到的地方直接使用即可，这样可以大大简化代码量。我们需要增加新功能也方便，提高了系统的扩展性。日志功能、事务管理和权限管理等场景都用到了AOP。</p><p><strong>AOP包含的几个概念</strong></p><ol><li>Jointpoint（连接点）：具体的切面点点抽象概念，可以是在字段、方法上，Spring中具体表现形式是PointCut（切入点），仅作用在方法上。</li><li>Advice（通知）: 在连接点进行的具体操作，如何进行增强处理的，分为前置、后置、异常、最终、环绕五种情况。</li><li>目标对象：被AOP框架进行增强处理的对象，也被称为被增强的对象。</li><li>AOP代理：AOP框架创建的对象，简单的说，代理就是对目标对象的加强。Spring中的AOP代理可以是JDK动态代理，也可以是CGLIB代理。</li><li>Weaving（织入）：将增强处理添加到目标对象中，创建一个被增强的对象的过程</li></ol><p>总结为一句话就是：在目标对象（target object）的某些方法（jointpoint）添加不同种类的操作（通知、增强操处理），最后通过某些方法（weaving、织入操作）实现一个新的代理目标对象。</p><h3 id="aop-有哪些应用场景" tabindex="-1">AOP 有哪些应用场景？ <a class="header-anchor" href="#aop-有哪些应用场景" aria-label="Permalink to &quot;AOP 有哪些应用场景？&quot;">​</a></h3><p>举几个例子：</p><ul><li>记录日志(调用方法后记录日志)</li><li>监控性能(统计方法运行时间)</li><li>权限控制(调用方法前校验是否有权限)</li><li>事务管理(调用方法前开启事务，调用方法后提交关闭事务 )</li><li>缓存优化(第一次调用查询数据库，将查询结果放入内存对象， 第二次调用，直接从内存对象返回，不需要查询数据库 )</li></ul><h3 id="有哪些aop-advice通知的类型" tabindex="-1">有哪些AOP Advice通知的类型？ <a class="header-anchor" href="#有哪些aop-advice通知的类型" aria-label="Permalink to &quot;有哪些AOP Advice通知的类型？&quot;">​</a></h3><p>特定 JoinPoint 处的 Aspect 所采取的动作称为 Advice。Spring AOP 使用一个 Advice 作为拦截器，在 JoinPoint “周围”维护一系列的拦截器。</p><ul><li><strong>前置通知</strong>（Before advice） ： 这些类型的 Advice 在 joinpoint 方法之前执行，并使用 @Before 注解标记进行配置。</li><li><strong>后置通知</strong>（After advice） ：这些类型的 Advice 在连接点方法之后执行，无论方法退出是正常还是异常返回，并使用 @After 注解标记进行配置。</li><li><strong>返回后通知</strong>（After return advice） ：这些类型的 Advice 在连接点方法正常执行后执行，并使用@AfterReturning 注解标记进行配置。</li><li><strong>环绕通知</strong>（Around advice） ：这些类型的 Advice 在连接点之前和之后执行，并使用 @Around 注解标记进行配置。</li><li><strong>抛出异常后通知</strong>（After throwing advice） ：仅在 joinpoint 方法通过抛出异常退出并使用 @AfterThrowing 注解标记配置时执行。</li></ul><h3 id="aop-有哪些实现方式" tabindex="-1">AOP 有哪些实现方式？ <a class="header-anchor" href="#aop-有哪些实现方式" aria-label="Permalink to &quot;AOP 有哪些实现方式？&quot;">​</a></h3><p>实现 AOP 的技术，主要分为两大类：</p><ul><li><strong>静态代理</strong> - 指使用 AOP 框架提供的命令进行编译，从而在编译阶段就可生成 AOP 代理类，因此也称为编译时增强； <ul><li>编译时编织（特殊编译器实现）</li><li>类加载时编织（特殊的类加载器实现）。</li></ul></li><li><strong>动态代理</strong> - 在运行时在内存中“临时”生成 AOP 动态代理类，因此也被称为运行时增强。 <ul><li>JDK 动态代理 <ul><li>JDK Proxy 是 Java 语言自带的功能，无需通过加载第三方类实现；</li><li>Java 对 JDK Proxy 提供了稳定的支持，并且会持续的升级和更新，Java 8 版本中的 JDK Proxy 性能相比于之前版本提升了很多；</li><li>JDK Proxy 是通过拦截器加反射的方式实现的；</li><li>JDK Proxy 只能代理实现接口的类；</li><li>JDK Proxy 实现和调用起来比较简单；</li></ul></li><li>CGLIB <ul><li>CGLib 是第三方提供的工具，基于 ASM 实现的，性能比较高；</li><li>CGLib 无需通过接口来实现，它是针对类实现代理，主要是对指定的类生成一个子类，它是通过实现子类的方式来完成调用的。</li></ul></li></ul></li></ul><h3 id="谈谈你对cglib的理解" tabindex="-1">谈谈你对CGLib的理解？ <a class="header-anchor" href="#谈谈你对cglib的理解" aria-label="Permalink to &quot;谈谈你对CGLib的理解？&quot;">​</a></h3><p>JDK 动态代理机制只能代理实现接口的类，一般没有实现接口的类不能进行代理。使用 CGLib 实现动态代理，完全不受代理类必须实现接口的限制。</p><p>CGLib 的原理是对指定目标类生成一个子类，并覆盖其中方法实现增强，但因为采用的是继承，所以不能对 final 修饰的类进行代理。</p><p>举例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>public class CGLibDemo {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // 需要动态代理的实际对象</span></span>
<span class="line"><span>    static class Sister  {</span></span>
<span class="line"><span>        public void sing() {</span></span>
<span class="line"><span>            System.out.println(&quot;I am Jinsha, a little sister.&quot;);</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    static class CGLibProxy implements MethodInterceptor {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        private Object target;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        public Object getInstance(Object target){</span></span>
<span class="line"><span>            this.target = target;</span></span>
<span class="line"><span>            Enhancer enhancer = new Enhancer();</span></span>
<span class="line"><span>            // 设置父类为实例类</span></span>
<span class="line"><span>            enhancer.setSuperclass(this.target.getClass());</span></span>
<span class="line"><span>            // 回调方法</span></span>
<span class="line"><span>            enhancer.setCallback(this);</span></span>
<span class="line"><span>            // 创建代理对象</span></span>
<span class="line"><span>            return enhancer.create();</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        @Override</span></span>
<span class="line"><span>        public Object intercept(Object o, Method method, Object[] objects, MethodProxy methodProxy) throws Throwable {</span></span>
<span class="line"><span>            System.out.println(&quot;introduce yourself...&quot;);</span></span>
<span class="line"><span>            Object result = methodProxy.invokeSuper(o,objects);</span></span>
<span class="line"><span>            System.out.println(&quot;score...&quot;);</span></span>
<span class="line"><span>            return result;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static void main(String[] args) {</span></span>
<span class="line"><span>        CGLibProxy cgLibProxy = new CGLibProxy();</span></span>
<span class="line"><span>        //获取动态代理类实例</span></span>
<span class="line"><span>        Sister proxySister = (Sister) cgLibProxy.getInstance(new Sister());</span></span>
<span class="line"><span>        System.out.println(&quot;CGLib Dynamic object name: &quot; + proxySister.getClass().getName());</span></span>
<span class="line"><span>        proxySister.sing();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>CGLib 的调用流程就是通过调用拦截器的 intercept 方法来实现对被代理类的调用。而拦截逻辑可以写在 intercept 方法的 invokeSuper(o, objects);的前后实现拦截。</p><h3 id="spring-aop和aspectj-aop有什么区别" tabindex="-1">Spring AOP和AspectJ AOP有什么区别？ <a class="header-anchor" href="#spring-aop和aspectj-aop有什么区别" aria-label="Permalink to &quot;Spring AOP和AspectJ AOP有什么区别？&quot;">​</a></h3><p>Spring AOP是属于运行时增强，而AspectJ是编译时增强。Spring AOP基于代理（Proxying），而AspectJ基于字节码操作（Bytecode Manipulation）。</p><p>Spring AOP已经集成了AspectJ，AspectJ应该算得上是Java生态系统中最完整的AOP框架了。AspectJ相比于Spring AOP功能更加强大，但是Spring AOP相对来说更简单。</p><p>如果我们的切面比较少，那么两者性能差异不大。但是，当切面太多的话，最好选择AspectJ，它比SpringAOP快很多。</p><h3 id="spring中的bean的作用域有哪些" tabindex="-1">Spring中的bean的作用域有哪些？ <a class="header-anchor" href="#spring中的bean的作用域有哪些" aria-label="Permalink to &quot;Spring中的bean的作用域有哪些？&quot;">​</a></h3><ol><li><p>singleton：唯一bean实例，Spring中的bean默认都是单例的。</p></li><li><p>prototype：每次请求都会创建一个新的bean实例。</p></li><li><p>request：每一次HTTP请求都会产生一个新的bean，该bean仅在当前HTTP request内有效。</p></li><li><p>session：每一次HTTP请求都会产生一个新的bean，该bean仅在当前HTTP session内有效。</p></li><li><p>global-session：全局session作用域，仅仅在基于Portlet的Web应用中才有意义，Spring5中已经没有了。Portlet是能够生成语义代码（例如HTML）片段的小型Java Web插件。它们基于Portlet容器，可以像Servlet一样处理HTTP请求。但是与Servlet不同，每个Portlet都有不同的会话。</p></li></ol><h3 id="spring中的单例bean的线程安全问题了解吗" tabindex="-1">Spring中的单例bean的线程安全问题了解吗？ <a class="header-anchor" href="#spring中的单例bean的线程安全问题了解吗" aria-label="Permalink to &quot;Spring中的单例bean的线程安全问题了解吗？&quot;">​</a></h3><p>大部分时候我们并没有在系统中使用多线程，所以很少有人会关注这个问题。单例bean存在线程问题，主要是因为当多个线程操作同一个对象的时候，对这个对象的非静态成员变量的写操作会存在线程安全问题。</p><p>有两种常见的解决方案：</p><p>1.在bean对象中尽量避免定义可变的成员变量（不太现实）。</p><p>2.在类中定义一个ThreadLocal成员变量，将需要的可变成员变量保存在ThreadLocal中（推荐的一种方式）。</p><h3 id="spring中的bean生命周期" tabindex="-1">Spring中的bean生命周期？ <a class="header-anchor" href="#spring中的bean生命周期" aria-label="Permalink to &quot;Spring中的bean生命周期？&quot;">​</a></h3><p><strong>Bean的完整生命周期经历了各种方法调用，这些方法可以划分为以下几类</strong>：</p><ul><li><strong>Bean自身的方法</strong>： 这个包括了Bean本身调用的方法和通过配置文件中<code>&lt;bean&gt;</code>的init-method和destroy-method指定的方法</li><li><strong>Bean级生命周期接口方法</strong>： 这个包括了BeanNameAware、BeanFactoryAware、ApplicationContextAware；当然也包括InitializingBean和DiposableBean这些接口的方法（可以被@PostConstruct和@PreDestroy注解替代)</li><li><strong>容器级生命周期接口方法</strong>： 这个包括了InstantiationAwareBeanPostProcessor 和 BeanPostProcessor 这两个接口实现，一般称它们的实现类为“后处理器”。</li><li><strong>工厂后处理器接口方法</strong>： 这个包括了AspectJWeavingEnabler, ConfigurationClassPostProcessor, CustomAutowireConfigurer等等非常有用的工厂后处理器接口的方法。工厂后处理器也是容器级的。在应用上下文装配配置文件之后立即调用。</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/e3d2334ec1.png" alt=""></p><p><strong>具体而言，流程如下</strong></p><ul><li>如果 BeanFactoryPostProcessor 和 Bean 关联, 则调用postProcessBeanFactory方法.(即首<strong>先尝试从Bean工厂中获取Bean</strong>)</li><li>如果 InstantiationAwareBeanPostProcessor 和 Bean 关联，则调用postProcessBeforeInstantiation方法</li><li>根据配置情况调用 Bean 构造方法<strong>实例化 Bean</strong>。</li><li>利用依赖注入完成 Bean 中所有<strong>属性值的配置注入</strong>。</li><li>如果 InstantiationAwareBeanPostProcessor 和 Bean 关联，则调用postProcessAfterInstantiation方法和postProcessProperties</li><li><strong>调用xxxAware接口</strong> (上图只是给了几个例子) <ul><li><strong>第一类Aware接口</strong><ul><li>如果 Bean 实现了 BeanNameAware 接口，则 Spring 调用 Bean 的 setBeanName() 方法传入当前 Bean 的 id 值。</li><li>如果 Bean 实现了 BeanClassLoaderAware 接口，则 Spring 调用 setBeanClassLoader() 方法传入classLoader的引用。</li><li>如果 Bean 实现了 BeanFactoryAware 接口，则 Spring 调用 setBeanFactory() 方法传入当前工厂实例的引用。</li></ul></li><li><strong>第二类Aware接口</strong><ul><li>如果 Bean 实现了 EnvironmentAware 接口，则 Spring 调用 setEnvironment() 方法传入当前 Environment 实例的引用。</li><li>如果 Bean 实现了 EmbeddedValueResolverAware 接口，则 Spring 调用 setEmbeddedValueResolver() 方法传入当前 StringValueResolver 实例的引用。</li><li>如果 Bean 实现了 ApplicationContextAware 接口，则 Spring 调用 setApplicationContext() 方法传入当前 ApplicationContext 实例的引用。</li><li>...</li></ul></li></ul></li><li>如果 BeanPostProcessor 和 Bean 关联，则 Spring 将调用该接口的预初始化方法 postProcessBeforeInitialzation() 对 Bean 进行加工操作，此处非常重要，Spring 的 AOP 就是利用它实现的。</li><li>如果 Bean 实现了 InitializingBean 接口，则 Spring 将调用 afterPropertiesSet() 方法。(或者有执行@PostConstruct注解的方法)</li><li>如果在配置文件中通过 <strong>init-method</strong> 属性指定了初始化方法，则调用该初始化方法。</li><li>如果 BeanPostProcessor 和 Bean 关联，则 Spring 将调用该接口的初始化方法 postProcessAfterInitialization()。此时，Bean 已经可以被应用系统使用了。</li><li>如果在 <code>&lt;bean&gt;</code> 中指定了该 Bean 的作用范围为 scope=&quot;singleton&quot;，则将该 Bean 放入 Spring IoC 的缓存池中，将触发 Spring 对该 Bean 的生命周期管理；如果在 <code>&lt;bean&gt;</code> 中指定了该 Bean 的作用范围为 scope=&quot;prototype&quot;，则将该 Bean 交给调用者，调用者管理该 Bean 的生命周期，Spring 不再管理该 Bean。</li><li>如果 Bean 实现了 DisposableBean 接口，则 Spring 会调用 destory() 方法将 Spring 中的 Bean 销毁；(或者有执行@PreDestroy注解的方法)</li><li>如果在配置文件中通过 <strong>destory-method</strong> 属性指定了 Bean 的销毁方法，则 Spring 将调用该方法对 Bean 进行销毁。</li></ul><h3 id="说说自己对于spring-mvc的了解" tabindex="-1">说说自己对于Spring MVC的了解？ <a class="header-anchor" href="#说说自己对于spring-mvc的了解" aria-label="Permalink to &quot;说说自己对于Spring MVC的了解？&quot;">​</a></h3><p>MVC是一种设计模式，Spring MVC是一款很优秀的MVC框架。Spring MVC可以帮助我们进行更简洁的Web层的开发，并且它天生与Spring框架集成。Spring MVC下我们一般把后端项目分为Service层（处理业务）、Dao层（数据库操作）、Entity层（实体类）、Controller层（控制层，返回数据给前台页面）。</p><p>Spring MVC的简单原理图如下：</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/34a119fede.png" alt=""></p><h3 id="spring-mvc的工作原理了解嘛" tabindex="-1">Spring MVC的工作原理了解嘛？ <a class="header-anchor" href="#spring-mvc的工作原理了解嘛" aria-label="Permalink to &quot;Spring MVC的工作原理了解嘛？&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/e4a434baaa.png" alt=""></p><p>流程说明：</p><p>1.客户端（浏览器）发送请求，直接请求到DispatcherServlet。</p><p>2.DispatcherServlet根据请求信息调用HandlerMapping，解析请求对应的Handler。</p><p>3.解析到对应的Handler（也就是我们平常说的Controller控制器）。</p><p>4.HandlerAdapter会根据Handler来调用真正的处理器来处理请求和执行相对应的业务逻辑。</p><p>5.处理器处理完业务后，会返回一个ModelAndView对象，Model是返回的数据对象，View是逻辑上的View。</p><p>6.ViewResolver会根据逻辑View去查找实际的View。</p><p>7.DispatcherServlet把返回的Model传给View（视图渲染）。</p><p>8.把View返回给请求者（浏览器）。</p><h3 id="spring框架中用到了哪些设计模式" tabindex="-1">Spring框架中用到了哪些设计模式？ <a class="header-anchor" href="#spring框架中用到了哪些设计模式" aria-label="Permalink to &quot;Spring框架中用到了哪些设计模式？&quot;">​</a></h3><p>举几个例子</p><p>1.工厂设计模式：Spring使用工厂模式通过BeanFactory和ApplicationContext创建bean对象。</p><p>2.代理设计模式：Spring AOP功能的实现。</p><p>3.单例设计模式：Spring中的bean默认都是单例的。</p><p>4.模板方法模式：Spring中的jdbcTemplate、hibernateTemplate等以Template结尾的对数据库操作的类，它们就使用到了模板模式。</p><p>5.包装器设计模式：我们的项目需要连接多个数据库，而且不同的客户在每次访问中根据需要会去访问不同的数据库。这种模式让我们可以根据客户的需求能够动态切换不同的数据源。</p><p>6.观察者模式：Spring事件驱动模型就是观察者模式很经典的一个应用。</p><p>7.适配器模式：Spring AOP的增强或通知（Advice）使用到了适配器模式、Spring MVC中也是用到了适配器模式适配Controller。</p><h3 id="component和-bean的区别是什么" tabindex="-1">@Component和@Bean的区别是什么？ <a class="header-anchor" href="#component和-bean的区别是什么" aria-label="Permalink to &quot;@Component和@Bean的区别是什么？&quot;">​</a></h3><p>1.作用对象不同。@Component注解作用于类，而@Bean注解作用于方法。</p><p>2.@Component注解通常是通过类路径扫描来自动侦测以及自动装配到Spring容器中（我们可以使用@ComponentScan注解定义要扫描的路径）。@Bean注解通常是在标有该注解的方法中定义产生这个bean，告诉Spring这是某个类的实例，当我需要用它的时候还给我。</p><p>3.@Bean注解比@Component注解的自定义性更强，而且很多地方只能通过@Bean注解来注册bean。比如当引用第三方库的类需要装配到Spring容器的时候，就只能通过@Bean注解来实现。</p><p>@Bean注解的使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>@Configuration</span></span>
<span class="line"><span>public class AppConfig {</span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public TransferService transferService() {</span></span>
<span class="line"><span>        return new TransferServiceImpl();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的代码相当于下面的XML配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;beans&gt;</span></span>
<span class="line"><span>    &lt;bean id=&quot;transferService&quot; class=&quot;com.yanggb.TransferServiceImpl&quot;/&gt;</span></span>
<span class="line"><span>&lt;/beans&gt;</span></span></code></pre></div><p>下面这个例子是无法通过@Component注解实现的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>@Bean</span></span>
<span class="line"><span>public OneService getService(status) {</span></span>
<span class="line"><span>    case (status)  {</span></span>
<span class="line"><span>        when 1:</span></span>
<span class="line"><span>                return new serviceImpl1();</span></span>
<span class="line"><span>        when 2:</span></span>
<span class="line"><span>                return new serviceImpl2();</span></span>
<span class="line"><span>        when 3:</span></span>
<span class="line"><span>                return new serviceImpl3();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="将一个类声明为spring的bean的注解有哪些" tabindex="-1">将一个类声明为Spring的bean的注解有哪些？ <a class="header-anchor" href="#将一个类声明为spring的bean的注解有哪些" aria-label="Permalink to &quot;将一个类声明为Spring的bean的注解有哪些？&quot;">​</a></h3><p>我们一般使用@Autowired注解去自动装配bean。而想要把一个类标识为可以用@Autowired注解自动装配的bean，可以采用以下的注解实现：</p><p>1.@Component注解。通用的注解，可标注任意类为Spring组件。如果一个Bean不知道属于哪一个层，可以使用@Component注解标注。</p><p>2.@Repository注解。对应持久层，即Dao层，主要用于数据库相关操作。</p><p>3.@Service注解。对应服务层，即Service层，主要涉及一些复杂的逻辑，需要用到Dao层（注入）。</p><p>4.@Controller注解。对应Spring MVC的控制层，即Controller层，主要用于接受用户请求并调用Service层的方法返回数据给前端页面。</p><h3 id="spring事务管理的方式有几种" tabindex="-1">Spring事务管理的方式有几种？ <a class="header-anchor" href="#spring事务管理的方式有几种" aria-label="Permalink to &quot;Spring事务管理的方式有几种？&quot;">​</a></h3><p>1.编程式事务：在代码中硬编码（不推荐使用）。</p><p>2.声明式事务：在配置文件中配置（推荐使用），分为基于XML的声明式事务和基于注解的声明式事务。</p><h3 id="spring事务中的隔离级别有哪几种" tabindex="-1">Spring事务中的隔离级别有哪几种？ <a class="header-anchor" href="#spring事务中的隔离级别有哪几种" aria-label="Permalink to &quot;Spring事务中的隔离级别有哪几种？&quot;">​</a></h3><p>在TransactionDefinition接口中定义了五个表示隔离级别的常量：</p><p>ISOLATION_DEFAULT：使用后端数据库默认的隔离级别，Mysql默认采用的REPEATABLE_READ隔离级别；Oracle默认采用的READ_COMMITTED隔离级别。</p><p>ISOLATION_READ_UNCOMMITTED：最低的隔离级别，允许读取尚未提交的数据变更，可能会导致脏读、幻读或不可重复读。</p><p>ISOLATION_READ_COMMITTED：允许读取并发事务已经提交的数据，可以阻止脏读，但是幻读或不可重复读仍有可能发生</p><p>ISOLATION_REPEATABLE_READ：对同一字段的多次读取结果都是一致的，除非数据是被本身事务自己所修改，可以阻止脏读和不可重复读，但幻读仍有可能发生。</p><p>ISOLATION_SERIALIZABLE：最高的隔离级别，完全服从ACID的隔离级别。所有的事务依次逐个执行，这样事务之间就完全不可能产生干扰，也就是说，该级别可以防止脏读、不可重复读以及幻读。但是这将严重影响程序的性能。通常情况下也不会用到该级别。</p><h3 id="spring事务中有哪几种事务传播行为" tabindex="-1">Spring事务中有哪几种事务传播行为？ <a class="header-anchor" href="#spring事务中有哪几种事务传播行为" aria-label="Permalink to &quot;Spring事务中有哪几种事务传播行为？&quot;">​</a></h3><p>在TransactionDefinition接口中定义了7个表示事务传播行为的常量。</p><p>支持当前事务的情况：</p><p>PROPAGATION_REQUIRED：如果当前存在事务，则加入该事务；如果当前没有事务，则创建一个新的事务。</p><p>PROPAGATION_SUPPORTS： 如果当前存在事务，则加入该事务；如果当前没有事务，则以非事务的方式继续运行。</p><p>PROPAGATION_MANDATORY： 如果当前存在事务，则加入该事务；如果当前没有事务，则抛出异常。（mandatory：强制性）。</p><p>不支持当前事务的情况：</p><p>PROPAGATION_REQUIRES_NEW： 创建一个新的事务，如果当前存在事务，则把当前事务挂起。</p><p>PROPAGATION_NOT_SUPPORTED： 以非事务方式运行，如果当前存在事务，则把当前事务挂起。</p><p>PROPAGATION_NEVER： 以非事务方式运行，如果当前存在事务，则抛出异常。</p><p>其他情况：</p><p>PROPAGATION_NESTED： 如果当前存在事务，则创建一个事务作为当前事务的嵌套事务来运行；如果当前没有事务，则该取值等价于PROPAGATION_REQUIRED。</p><h3 id="bean-factory和applicationcontext有什么区别" tabindex="-1">Bean Factory和ApplicationContext有什么区别？ <a class="header-anchor" href="#bean-factory和applicationcontext有什么区别" aria-label="Permalink to &quot;Bean Factory和ApplicationContext有什么区别？&quot;">​</a></h3><p>ApplicationContex提供了一种解析文本消息的方法，一种加载文件资源（如图像）的通用方法，它们可以将事件发布到注册为侦听器的bean。此外，可以在应用程序上下文中以声明方式处理容器中的容器或容器上的操作，这些操作必须以编程方式与Bean Factory一起处理。ApplicationContext实现MessageSource，一个用于获取本地化消息的接口，实际的实现是可插入的。</p><h3 id="如何定义bean的范围" tabindex="-1">如何定义bean的范围？ <a class="header-anchor" href="#如何定义bean的范围" aria-label="Permalink to &quot;如何定义bean的范围？&quot;">​</a></h3><p>在Spring中定义一个时，我们也可以为bean声明一个范围。它可以通过bean定义中的scope属性定义。例如，当Spring每次需要生成一个新的bean实例时，bean&#39;sscope属性就是原型。另一方面，当每次需要Spring都必须返回相同的bean实例时，bean scope属性必须设置为singleton。</p><h3 id="可以通过多少种方式完成依赖注入" tabindex="-1">可以通过多少种方式完成依赖注入？ <a class="header-anchor" href="#可以通过多少种方式完成依赖注入" aria-label="Permalink to &quot;可以通过多少种方式完成依赖注入？&quot;">​</a></h3><p>通常，依赖注入可以通过三种方式完成，即：</p><ul><li>构造函数注入</li><li>setter 注入</li><li>接口注入</li></ul><h2 id="spring-boot" tabindex="-1">Spring Boot <a class="header-anchor" href="#spring-boot" aria-label="Permalink to &quot;Spring Boot&quot;">​</a></h2><h3 id="什么是springboot" tabindex="-1">什么是SpringBoot？ <a class="header-anchor" href="#什么是springboot" aria-label="Permalink to &quot;什么是SpringBoot？&quot;">​</a></h3><p>Spring Boot 是 Spring 开源组织下的子项目，是 Spring 组件一站式解决方案，主要是简化了使用 Spring 的难度，简省了繁重的配置，提供了各种启动器，开发者能快速上手。</p><ul><li>用来简化Spring应用的初始搭建以及开发过程，使用特定的方式来进行配置</li><li>创建独立的Spring引用程序main方法运行</li><li>嵌入的tomcat无需部署war文件</li><li>简化maven配置</li><li>自动配置Spring添加对应的功能starter自动化配置</li><li>SpringBoot来简化Spring应用开发，约定大于配置，去繁化简</li></ul><h3 id="为什么使用springboot" tabindex="-1">为什么使用SpringBoot？ <a class="header-anchor" href="#为什么使用springboot" aria-label="Permalink to &quot;为什么使用SpringBoot？&quot;">​</a></h3><ul><li>独立运行</li></ul><p>Spring Boot 而且内嵌了各种 servlet 容器，Tomcat、Jetty 等，现在不再需要打成war 包部署到容器中，Spring Boot 只要打成一个可执行的 jar 包就能独立运行，所有的依赖包都在一个 jar 包内。</p><ul><li>简化配置</li></ul><p>spring-boot-starter-web 启动器自动依赖其他组件，简少了 maven 的配置。</p><ul><li>自动配置</li></ul><p>Spring Boot 能根据当前类路径下的类、jar 包来自动配置 bean，如添加一个 spring</p><p>boot-starter-web 启动器就能拥有 web 的功能，无需其他配置。</p><ul><li>无代码生成和XML配置</li></ul><p>Spring Boot 配置过程中无代码生成，也无需 XML 配置文件就能完成所有配置工作，这一切都是借助于条件注解完成的，这也是 Spring4.x 的核心功能之一。</p><ul><li>应用监控</li></ul><p>Spring Boot 提供一系列端点可以监控服务及应用，做健康检测。</p><h3 id="spring、spring-mvc和springboot有什么区别" tabindex="-1">Spring、Spring MVC和SpringBoot有什么区别？ <a class="header-anchor" href="#spring、spring-mvc和springboot有什么区别" aria-label="Permalink to &quot;Spring、Spring MVC和SpringBoot有什么区别？&quot;">​</a></h3><ul><li>Spring</li></ul><p>Spring最重要的特征是依赖注入。所有Spring Modules不是依赖注入就是IOC控制反转。</p><p>当我们恰当的使用DI或者是IOC的时候，可以开发松耦合应用。</p><ul><li>Spring MVC</li></ul><p>Spring MVC提供了一种分离式的方法来开发Web应用。通过运用像DispatcherServelet，ModelAndView 和 ViewResolver 等一些简单的概念，开发 Web 应用将会变的非常简单。</p><ul><li>SpringBoot</li></ul><p>Spring和Spring MVC的问题在于需要配置大量的参数。</p><p>SpringBoot通过一个自动配置和启动的项来解决这个问题。</p><h3 id="springboot自动配置的原理" tabindex="-1">SpringBoot自动配置的原理? <a class="header-anchor" href="#springboot自动配置的原理" aria-label="Permalink to &quot;SpringBoot自动配置的原理?&quot;">​</a></h3><p>在Spring程序main方法中，添加@SpringBootApplication或者@EnableAutoConfiguration会自动去maven中读取每个starter中的spring.factories文件，该文件里配置了所有需要被创建的Spring容器中的bean</p><h3 id="spring-boot的核心注解是哪些-他主由哪几个注解组成的" tabindex="-1">Spring Boot的核心注解是哪些？他主由哪几个注解组成的？ <a class="header-anchor" href="#spring-boot的核心注解是哪些-他主由哪几个注解组成的" aria-label="Permalink to &quot;Spring Boot的核心注解是哪些？他主由哪几个注解组成的？&quot;">​</a></h3><p>启动类上面的注解是@SpringBootApplication，他也是SpringBoot的核心注解，主要组合包含了以下3个注解：</p><ul><li>@SpringBootConfiguration：组合了@Configuration注解，实现配置文件的功能；</li><li>@EnableAutoConfiguration：打开自动配置的功能，也可以关闭某个自动配置的选项，如关闭数据源自动配置的功能：</li><li>@SpringBootApplication(exclude={DataSourceAutoConfiguration.class})；</li><li>@ComponentScan：Spring组件扫描。</li></ul><h3 id="springboot的核心配置文件有哪几个-他们的区别是什么" tabindex="-1">SpringBoot的核心配置文件有哪几个？他们的区别是什么？ <a class="header-anchor" href="#springboot的核心配置文件有哪几个-他们的区别是什么" aria-label="Permalink to &quot;SpringBoot的核心配置文件有哪几个？他们的区别是什么？&quot;">​</a></h3><p>SpringBoot的核心配置文件是application和bootstrap配置文件。</p><p>application配置文件这个容易理解，主要用于Spring Boot项目的自动化配置。</p><p>bootstrap配置文件有以下几个应用场景：</p><ul><li>使用Spring Cloud Config配置中心时，这时需要在bootstrap配置文件中添加连接到配置中心的配置属性来加载外部配置中心的配置信息；</li><li>一些固定的不能被覆盖的属性；</li><li>一些加密/解密的场景；</li></ul><h3 id="什么是spring-boot-starter-有哪些常用的" tabindex="-1">什么是Spring Boot Starter？有哪些常用的？ <a class="header-anchor" href="#什么是spring-boot-starter-有哪些常用的" aria-label="Permalink to &quot;什么是Spring Boot Starter？有哪些常用的？&quot;">​</a></h3><p>和自动配置一样，Spring Boot Starter的目的也是简化配置，而Spring Boot Starter解决的是依赖管理配置复杂的问题，有了它，当我需要构建一个Web应用程序时，不必再遍历所有的依赖包，一个一个地添加到项目的依赖管理中，而是只需要一个配置spring-boot-starter-web, 同理，如果想引入持久化功能，可以配置spring-boot-starter-data-jpa：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>    &lt;artifactId&gt;spring-boot-starter-web&lt;/artifactId&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>Spring Boot 也提供了其它的启动器项目包括，包括用于开发特定类型应用程序的典型依赖项。</p><p>spring-boot-starter-web-services - SOAP Web Services</p><p>spring-boot-starter-web - Web 和 RESTful 应用程序</p><p>spring-boot-starter-test - 单元测试和集成测试</p><p>spring-boot-starter-jdbc - 传统的 JDBC</p><p>spring-boot-starter-hateoas - 为服务添加 HATEOAS 功能</p><p>spring-boot-starter-security - 使用 SpringSecurity 进行身份验证和授权</p><p>spring-boot-starter-data-jpa - 带有 Hibernate 的 Spring Data JPA</p><p>spring-boot-starter-data-rest - 使用 Spring Data REST 公布简单的 REST 服务</p><h3 id="spring-boot-starter-parent有什么作用" tabindex="-1">spring-boot-starter-parent有什么作用？ <a class="header-anchor" href="#spring-boot-starter-parent有什么作用" aria-label="Permalink to &quot;spring-boot-starter-parent有什么作用？&quot;">​</a></h3><p>我们知道，新建一个SpringBoot项目，默认都是有parent的，这个parent就是spring-boot-starter-parent，spring-boot-starter-parent主要有如下作用：</p><ul><li>定义了Java编译版本</li><li>使用UTF-8格式编码</li><li>继承自spring-boor-dependencies，这里面定义了依赖的版本，也正是因为继承了这个依赖，所以我们在写依赖时才不需要写版本号</li><li>执行打包操作的配置</li><li>自动化的资源过滤</li><li>自动化的插件配置</li></ul><h3 id="如何自定义spring-boot-starter" tabindex="-1">如何自定义Spring Boot Starter？ <a class="header-anchor" href="#如何自定义spring-boot-starter" aria-label="Permalink to &quot;如何自定义Spring Boot Starter？&quot;">​</a></h3><ul><li>实现功能</li><li>添加Properties</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>@Data</span></span>
<span class="line"><span>@ConfigurationProperties(prefix = &quot;com.pdai&quot;)</span></span>
<span class="line"><span>public class DemoProperties {</span></span>
<span class="line"><span>    private String version;</span></span>
<span class="line"><span>    private String name;</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>添加AutoConfiguration</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>@Configuration</span></span>
<span class="line"><span>@EnableConfigurationProperties(DemoProperties.class)</span></span>
<span class="line"><span>public class DemoAutoConfiguration {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Bean</span></span>
<span class="line"><span>    public com.pdai.demo.module.DemoModule demoModule(DemoProperties properties){</span></span>
<span class="line"><span>        com.pdai.demo.module.DemoModule demoModule = new com.pdai.demo.module.DemoModule();</span></span>
<span class="line"><span>        demoModule.setName(properties.getName());</span></span>
<span class="line"><span>        demoModule.setVersion(properties.getVersion());</span></span>
<span class="line"><span>        return demoModule;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>添加spring.factory</li></ul><p>在META-INF下创建spring.factory文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>org.springframework.boot.autoconfigure.EnableAutoConfiguration=\\</span></span>
<span class="line"><span>com.pdai.demospringbootstarter.DemoAutoConfiguration</span></span></code></pre></div><ul><li>install</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/f857f0860d.png" alt=""></p><h3 id="为什么需要spring-boot-maven-plugin" tabindex="-1">为什么需要spring-boot-maven-plugin？ <a class="header-anchor" href="#为什么需要spring-boot-maven-plugin" aria-label="Permalink to &quot;为什么需要spring-boot-maven-plugin？&quot;">​</a></h3><p>spring-boot-maven-plugin提供了一些像jar一样打包或者运行应用程序的命令。</p><ol><li>spring-boot:run 运行SpringBoot应用程序；</li><li>spring-boot:repackage 重新打包你的jar包或者是war包使其可执行</li><li>spring-boot:start和spring-boot:stop管理Spring Boot应用程序的生命周期</li><li>spring-boot:build-info生成执行器可以使用的构造信息</li></ol><h3 id="springboot-打成jar和普通的jar有什么区别" tabindex="-1">SpringBoot 打成jar和普通的jar有什么区别？ <a class="header-anchor" href="#springboot-打成jar和普通的jar有什么区别" aria-label="Permalink to &quot;SpringBoot 打成jar和普通的jar有什么区别？&quot;">​</a></h3><p>Spring Boot 项目最终打包成的 jar 是可执行 jar ，这种 jar 可以直接通过java -jar xxx.jar命令来运行，这种 jar 不可以作为普通的 jar 被其他项目依赖，即使依赖了也无法使用其中的类。</p><p>Spring Boot 的 jar 无法被其他项目依赖，主要还是他和普通 jar 的结构不同。普通的 jar 包，解压后直接就是包名，包里就是我们的代码，而 Spring Boot 打包成的可执行 jar 解压后，在 \\BOOT-INF\\classes目录下才是我们的代码，因此无法被直接引用。如果非要引用，可以在 pom.xml 文件中增加配置，将 Spring Boot 项目打包成两个 jar ，一个可执行，一个可引用。</p><h3 id="如何使用spring-boot实现异常处理" tabindex="-1">如何使用Spring Boot实现异常处理？ <a class="header-anchor" href="#如何使用spring-boot实现异常处理" aria-label="Permalink to &quot;如何使用Spring Boot实现异常处理？&quot;">​</a></h3><p>Spring提供了一种使用ControllerAdvice处理异常的非常有用的方法。通过实现一个ControlerAdvice类，来处理控制类抛出的所有异常。</p><h3 id="springboot-实现热部署有哪几种方式" tabindex="-1">SpringBoot 实现热部署有哪几种方式？ <a class="header-anchor" href="#springboot-实现热部署有哪几种方式" aria-label="Permalink to &quot;SpringBoot 实现热部署有哪几种方式？&quot;">​</a></h3><p>主要有两种方式：</p><ul><li>Spring Loaded</li><li>Spring-boot-devtools</li></ul><h3 id="spring-boot中的监视器是什么" tabindex="-1">Spring Boot中的监视器是什么？ <a class="header-anchor" href="#spring-boot中的监视器是什么" aria-label="Permalink to &quot;Spring Boot中的监视器是什么？&quot;">​</a></h3><p>Spring boot actuator是spring启动框架中的重要功能之一。Spring boot监视器可帮助您访问生产环境中正在运行的应用程序的当前状态。</p><p>有几个指标必须在生产环境中进行检查和监控。即使一些外部应用程序可能正在使用这些服务来向相关人员触发警报消息。监视器模块公开了一组可直接作为HTTP URL访问的REST端点来检查状态。</p><h3 id="spring-boot-可以兼容老-spring-项目吗" tabindex="-1">Spring Boot 可以兼容老 Spring 项目吗？ <a class="header-anchor" href="#spring-boot-可以兼容老-spring-项目吗" aria-label="Permalink to &quot;Spring Boot 可以兼容老 Spring 项目吗？&quot;">​</a></h3><p>可以兼容，使用 @ImportResource 注解导入老 Spring 项目配置文件。</p><h2 id="spring-security" tabindex="-1">Spring Security <a class="header-anchor" href="#spring-security" aria-label="Permalink to &quot;Spring Security&quot;">​</a></h2><h3 id="什么是spring-security-核心功能" tabindex="-1">什么是Spring Security？核心功能？ <a class="header-anchor" href="#什么是spring-security-核心功能" aria-label="Permalink to &quot;什么是Spring Security？核心功能？&quot;">​</a></h3><p>Spring Security是基于Spring的安全框架.它提供全面的安全性解决方案,同时在Web请求级别和调用级别确认和授权.在Spring Framework基础上,Spring Security充分利用了依赖注入(DI)和面向切面编程(AOP)功能,为应用系统提供声明式的安全访问控制功能,建晒了为企业安全控制编写大量重复代码的工作,是一个轻量级的安全框架,并且很好集成Spring MVC</p><p>spring security 的核心功能主要包括：</p><ul><li>认证(Authentication)：指的是验证某个用户是否为系统中的合法主体，也就是说用户能否访问该系统。</li><li>授权(Authorization)：指的是验证某个用户是否有权限执行某个操作</li><li>攻击防护：指的是防止伪造身份</li></ul><h3 id="spring-security的原理" tabindex="-1">Spring Security的原理? <a class="header-anchor" href="#spring-security的原理" aria-label="Permalink to &quot;Spring Security的原理?&quot;">​</a></h3><p>简单谈谈其中的要点</p><ul><li><strong>基于Filter技术实现?</strong></li></ul><p>首先SpringSecurity是基于Filter技术实现的。Spring通过DelegatingFilterProxy建立Web容器和Spring ApplicationContext的联系，而SpringSecurity使用FilterChainProxy 注册SecurityFilterChain。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/471cdf3346.png" alt=""></p><ul><li><strong>认证模块的实现</strong>？</li></ul><p><strong>SecurityContextHolder</strong>(用于存储授权信息)</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/70f3acf862.png" alt=""></p><p>手动授权的例子（SecurityContextHolder.getContext().setAuthentication(authentication)这种授权方式多线程不安全）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>SecurityContext context = SecurityContextHolder.createEmptyContext(); </span></span>
<span class="line"><span>Authentication authentication =</span></span>
<span class="line"><span>    new TestingAuthenticationToken(&quot;username&quot;, &quot;password&quot;, &quot;ROLE_USER&quot;); </span></span>
<span class="line"><span>context.setAuthentication(authentication);</span></span>
<span class="line"><span>SecurityContextHolder.setContext(context);</span></span></code></pre></div><p>除了手动授权外，<strong>SpringSecurity通过AuthenticationManager和ProviderManager进行授权</strong>。其中AuthenticationProvider代表不同的认证机制（最常用的账号/密码）。</p><p><strong>ProviderManager</strong></p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/c9b1c053e3.png" alt=""></p><p><strong>AuthenticationManager</strong></p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/0adac50d88.png" alt=""></p><ul><li><strong>授权模块的实现</strong>？</li></ul><p>认证完成之后，SpringSecurity通过AccessDecisionManager 完成授权操作。除了全局的授权配置之外，也可以通过@PreAuthorize, @PreFilter, @PostAuthorize , @PostFilter注解实现方法级别的权限控制。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/35c50b1b34.png" alt=""></p><h3 id="spring-security基于用户名和密码的认证模式流程" tabindex="-1">Spring Security基于用户名和密码的认证模式流程？ <a class="header-anchor" href="#spring-security基于用户名和密码的认证模式流程" aria-label="Permalink to &quot;Spring Security基于用户名和密码的认证模式流程？&quot;">​</a></h3><p>请求的用户名密码可以通过表单登录，基础认证，数字认证三种方式从HttpServletRequest中获得，用于认证的数据源策略有内存，数据库，ldap,自定义等。</p><p>拦截未授权的请求，重定向到登录页面</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/125623f781.png" alt=""></p><p>表单登录的过程，进行账号密码认证</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/6f1940ba08.png" alt=""></p><h2 id="日志框架" tabindex="-1">日志框架 <a class="header-anchor" href="#日志框架" aria-label="Permalink to &quot;日志框架&quot;">​</a></h2><h3 id="什么是日志系统和日志门面-分别有哪些框架" tabindex="-1">什么是日志系统和日志门面？分别有哪些框架？ <a class="header-anchor" href="#什么是日志系统和日志门面-分别有哪些框架" aria-label="Permalink to &quot;什么是日志系统和日志门面？分别有哪些框架？&quot;">​</a></h3><p>日志系统是具体的日志框架，日志门面是不提供日志的具体实现，而是在运行时动态的绑定日志实现组件来工作，是一种外观模式。</p><ul><li><p><strong>日志系统</strong></p><ul><li>java.util.logging (<strong>JUL</strong>)，JDK1.4 开始，通过 java.util.logging 提供日志功能。虽然是官方自带的log lib，JUL的使用确不广泛。</li><li><strong>Log4j</strong>，Log4j 是 apache 的一个开源项目，创始人 Ceki Gulcu。Log4j 应该说是 Java 领域资格最老，应用最广的日志工具。Log4j 是高度可配置的，并可通过在运行时的外部文件配置。它根据记录的优先级别，并提供机制，以指示记录信息到许多的目的地，诸如：数据库，文件，控制台，UNIX 系统日志等。Log4j 的短板在于性能，在Logback 和 Log4j2 出来之后，Log4j的使用也减少了。</li><li><strong>Logback</strong>，Logback 是由 log4j 创始人 Ceki Gulcu 设计的又一个开源日志组件，是作为 Log4j 的继承者来开发的，提供了性能更好的实现，异步 logger，Filter等更多的特性。</li><li><strong>Log4j2</strong>，维护 Log4j 的人为了性能又搞出了 Log4j2。Log4j2 和 Log4j1.x 并不兼容，设计上很大程度上模仿了 SLF4J/Logback，性能上也获得了很大的提升。Log4j2 也做了 Facade/Implementation 分离的设计，分成了 log4j-api 和 log4j-core。</li></ul></li><li><p><strong>日志门面</strong></p><ul><li><strong>common-logging</strong>，common-logging 是 apache 的一个开源项目。也称Jakarta Commons Logging，缩写 JCL。</li><li><strong>slf4j</strong>, 全称为 Simple Logging Facade for Java，即 java 简单日志门面。作者又是 Ceki Gulcu！这位大神写了 Log4j、Logback 和 slf4j。类似于 Common-Logging，slf4j 是对不同日志框架提供的一个 API 封装，可以在部署的时候不修改任何配置即可接入一种日志实现方案。但是，slf4j 在编译时静态绑定真正的 Log 库。使用 SLF4J 时，如果你需要使用某一种日志实现，那么你必须选择正确的 SLF4J 的 jar 包的集合（各种桥接包）。</li></ul></li></ul><h3 id="日志库中使用桥接模式解决什么问题" tabindex="-1">日志库中使用桥接模式解决什么问题？ <a class="header-anchor" href="#日志库中使用桥接模式解决什么问题" aria-label="Permalink to &quot;日志库中使用桥接模式解决什么问题？&quot;">​</a></h3><ul><li>什么是桥接呢？</li></ul><p>假如你正在开发应用程序所调用的组件当中已经使用了 common-logging，这时你需要 jcl-over-slf4j.jar 把日志信息输出重定向到 slf4j-api，slf4j-api 再去调用 slf4j 实际依赖的日志组件。这个过程称为桥接。下图是官方的 slf4j 桥接策略图：</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/0b4cfebaa6.png" alt=""></p><p>从图中应该可以看出，无论你的老项目中使用的是 common-logging 或是直接使用 log4j、java.util.logging，都可以使用对应的桥接 jar 包来解决兼容问题。</p><ul><li>slf4j 兼容 common-logging</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>  &lt;groupId&gt;org.slf4j&lt;/groupId&gt;</span></span>
<span class="line"><span>  &lt;artifactId&gt;jcl-over-slf4j&lt;/artifactId&gt;</span></span>
<span class="line"><span>  &lt;version&gt;1.7.12&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><ul><li>slf4j 兼容 log4j</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;org.slf4j&lt;/groupId&gt;</span></span>
<span class="line"><span>    &lt;artifactId&gt;log4j-over-slf4j&lt;/artifactId&gt;</span></span>
<span class="line"><span>    &lt;version&gt;1.7.12&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><h3 id="在日志配置时会考虑哪些点" tabindex="-1">在日志配置时会考虑哪些点？ <a class="header-anchor" href="#在日志配置时会考虑哪些点" aria-label="Permalink to &quot;在日志配置时会考虑哪些点？&quot;">​</a></h3><ul><li>支持日志路径，日志level等配置</li><li>日志控制配置通过application.yml下发</li><li>按天生成日志，当天的日志&gt;50MB回滚</li><li>最多保存10天日志</li><li>生成的日志中Pattern自定义</li><li>Pattern中添加用户自定义的MDC字段，比如用户信息(当前日志是由哪个用户的请求产生)，request信息。此种方式可以通过AOP切面控制，在MDC中添加requestID，在spring-logback.xml中配置Pattern。</li><li>根据不同的运行环境设置Profile - dev，test，product</li><li>对控制台，Err和全量日志分别配置</li><li>对第三方包路径日志控制</li></ul><h3 id="对java日志组件选型的建议" tabindex="-1">对Java日志组件选型的建议？ <a class="header-anchor" href="#对java日志组件选型的建议" aria-label="Permalink to &quot;对Java日志组件选型的建议？&quot;">​</a></h3><p>slf4j已经成为了Java日志组件的明星选手，可以完美替代JCL，使用JCL桥接库也能完美兼容一切使用JCL作为日志门面的类库，现在的新系统已经没有不使用slf4j作为日志API的理由了。</p><p>日志记录服务方面，log4j在功能上输于logback和log4j2，在性能方面log4j2则全面超越log4j和logback。所以新系统应该在logback和log4j2中做出选择，对于性能有很高要求的系统，应优先考虑log4j2。</p><h3 id="对日志架构使用比较好的实践" tabindex="-1">对日志架构使用比较好的实践？ <a class="header-anchor" href="#对日志架构使用比较好的实践" aria-label="Permalink to &quot;对日志架构使用比较好的实践？&quot;">​</a></h3><p>说几个点：</p><ul><li>总是使用Log Facade，而不是具体Log Implementation</li><li>只添加一个 Log Implementation依赖</li><li>具体的日志实现依赖应该设置为optional和使用runtime scope</li><li>如果有必要, 排除依赖的第三方库中的Log Impementation依赖</li><li>避免为不会输出的log付出代价</li><li>日志格式中最好不要使用行号，函数名等字段</li></ul><h3 id="对现有系统日志架构的改造建议" tabindex="-1">对现有系统日志架构的改造建议？ <a class="header-anchor" href="#对现有系统日志架构的改造建议" aria-label="Permalink to &quot;对现有系统日志架构的改造建议？&quot;">​</a></h3><p>如果现有系统使用JCL作为日志门面，又确实面临着JCL的ClassLoader机制带来的问题，完全可以引入slf4j并通过桥接库将JCL api输出的日志桥接至slf4j，再通过适配库适配至现有的日志输出服务（如log4j），如下图：</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/dcdf2b9538.png" alt=""></p><p>这样做不需要任何代码级的改造，就可以解决JCL的ClassLoader带来的问题，但没有办法享受日志模板等slf4j的api带来的优点。不过之后在现系统上开发的新功能就可以使用slf4j的api了，老代码也可以分批进行改造。</p><p>如果现有系统使用JCL作为日志门面，又头疼JCL不支持logback和log4j2等新的日志服务，也可以通过桥接库以slf4j替代JCL，但同样无法直接享受slf4j api的优点。</p><p>如果想要使用slf4j的api，那么就不得不进行代码改造了，当然改造也可以参考1中提到的方式逐步进行。</p><p>如果现系统面临着log4j的性能问题，可以使用Apache Logging提供的log4j到log4j2的桥接库log4j-1.2-api，把通过log4j api输出的日志桥接至log4j2。这样可以最快地使用上log4j2的先进性能，但组件中缺失了slf4j，对后续进行日志架构改造的灵活性有影响。另一种办法是先把log4j桥接至slf4j，再使用slf4j到log4j2的适配库。这样做稍微麻烦了一点，但可以逐步将系统中的日志输出标准化为使用slf4j的api，为后面的工作打好基础。</p><h2 id="tomcat" tabindex="-1">Tomcat <a class="header-anchor" href="#tomcat" aria-label="Permalink to &quot;Tomcat&quot;">​</a></h2><h3 id="tomcat-整体架构的设计" tabindex="-1">Tomcat 整体架构的设计？ <a class="header-anchor" href="#tomcat-整体架构的设计" aria-label="Permalink to &quot;Tomcat 整体架构的设计？&quot;">​</a></h3><p>从组件的角度看</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/6f656e0334.jpeg" alt=""></p><ul><li><p><strong>Server</strong>: 表示服务器，它提供了一种优雅的方式来启动和停止整个系统，不必单独启停连接器和容器；它是Tomcat构成的顶级构成元素，所有一切均包含在Server中；</p></li><li><p><strong>Service</strong>: 表示服务，Server可以运行多个服务。比如一个Tomcat里面可运行订单服务、支付服务、用户服务等等；Server的实现类StandardServer可以包含一个到多个Services, Service的实现类为StandardService调用了容器(Container)接口，其实是调用了Servlet Engine(引擎)，而且StandardService类中也指明了该Service归属的Server;</p></li><li><p><strong>Container</strong>: 表示容器，可以看做Servlet容器；引擎(Engine)、主机(Host)、上下文(Context)和Wraper均继承自Container接口，所以它们都是容器。</p><ul><li>Engine -- 引擎</li><li>Host -- 主机</li><li>Context -- 上下文</li><li>Wrapper -- 包装器</li></ul></li><li><p><strong>Connector</strong>: 表示连接器, <strong>它将Service和Container连接起来</strong>，首先它需要注册到一个Service，它的作用就是把来自客户端的请求转发到Container(容器)，这就是它为什么称作连接器, 它支持的协议如下：</p><ul><li>支持AJP协议</li><li>支持Http协议</li><li>支持Https协议</li></ul></li><li><p><strong>Service内部</strong>还有各种支撑组件，下面简单罗列一下这些组件</p><ul><li>Manager -- 管理器，用于管理会话Session</li><li>Logger -- 日志器，用于管理日志</li><li>Loader -- 加载器，和类加载有关，只会开放给Context所使用</li><li>Pipeline -- 管道组件，配合Valve实现过滤器功能</li><li>Valve -- 阀门组件，配合Pipeline实现过滤器功能</li><li>Realm -- 认证授权组件</li></ul></li></ul><h3 id="tomcat-一个请求的处理流程" tabindex="-1">Tomcat 一个请求的处理流程？ <a class="header-anchor" href="#tomcat-一个请求的处理流程" aria-label="Permalink to &quot;Tomcat 一个请求的处理流程？&quot;">​</a></h3><p>假设来自客户的请求为：<code>http://localhost:8080/test/index.jsp</code> 请求被发送到本机端口8080，被在那里侦听的Coyote HTTP/1.1 Connector,然后</p><ul><li>Connector把该请求交给它所在的Service的Engine来处理，并等待Engine的回应</li><li>Engine获得请求localhost:8080/test/index.jsp，匹配它所有虚拟主机Host</li><li>Engine匹配到名为localhost的Host(即使匹配不到也把请求交给该Host处理，因为该Host被定义为该Engine的默认主机)</li><li>localhost Host获得请求/test/index.jsp，匹配它所拥有的所有Context</li><li>Host匹配到路径为/test的Context(如果匹配不到就把该请求交给路径名为&quot;&quot;的Context去处理)</li><li>path=&quot;/test&quot;的Context获得请求/index.jsp，在它的mapping table中寻找对应的servlet</li><li>Context匹配到URL PATTERN为*.jsp的servlet，对应于JspServlet类，构造HttpServletRequest对象和HttpServletResponse对象，作为参数调用JspServlet的doGet或doPost方法</li><li>Context把执行完了之后的HttpServletResponse对象返回给Host</li><li>Host把HttpServletResponse对象返回给Engine</li><li>Engine把HttpServletResponse对象返回给Connector</li><li>Connector把HttpServletResponse对象返回给客户browser</li></ul><h3 id="tomcat-中类加载机制" tabindex="-1">Tomcat 中类加载机制？ <a class="header-anchor" href="#tomcat-中类加载机制" aria-label="Permalink to &quot;Tomcat 中类加载机制？&quot;">​</a></h3><p>在Bootstrap中我们可以看到有如下三个classloader</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>ClassLoader commonLoader = null;</span></span>
<span class="line"><span>ClassLoader catalinaLoader = null;</span></span>
<span class="line"><span>ClassLoader sharedLoader = null;</span></span></code></pre></div><ul><li><strong>为什么要设计多个类加载器</strong>？</li></ul><blockquote><p>如果所有的类都使用一个类加载器来加载，会出现什么问题呢？</p></blockquote><p>假如我们自己编写一个类<code>java.util.Object</code>，它的实现可能有一定的危险性或者隐藏的bug。而我们知道Java自带的核心类里面也有<code>java.util.Object</code>，如果JVM启动的时候先行加载的是我们自己编写的<code>java.util.Object</code>，那么就有可能出现安全问题！</p><p>所以，Sun（后被Oracle收购）采用了另外一种方式来保证最基本的、也是最核心的功能不会被破坏。你猜的没错，那就是双亲委派模式！</p><ul><li><strong>什么是双亲委派模型</strong>？</li></ul><blockquote><p>双亲委派模型解决了类错乱加载的问题，也设计得非常精妙。</p></blockquote><p>双亲委派模式对类加载器定义了层级，每个类加载器都有一个父类加载器。在一个类需要加载的时候，首先委派给父类加载器来加载，而父类加载器又委派给祖父类加载器来加载，以此类推。如果父类及上面的类加载器都加载不了，那么由当前类加载器来加载，并将被加载的类缓存起来。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/90606a12c0.png" alt=""></p><p>所以上述类是这么加载的</p><ul><li><p>Java自带的核心类 -- 由启动类加载器加载</p></li><li><p>Java支持的可扩展类 -- 由扩展类加载器加载</p></li><li><p>我们自己编写的类 -- 默认由应用程序类加载器或其子类加载</p></li><li><p><strong>为什么Tomcat的类加载器也不是双亲委派模型</strong>？</p></li></ul><p>Java默认的类加载机制是通过双亲委派模型来实现的，而Tomcat实现的方式又和双亲委派模型有所区别。</p><p><strong>原因在于一个Tomcat容器允许同时运行多个Web程序，每个Web程序依赖的类又必须是相互隔离的</strong>。因此，如果Tomcat使用双亲委派模式来加载类的话，将导致Web程序依赖的类变为共享的。</p><p>举个例子，假如我们有两个Web程序，一个依赖A库的1.0版本，另一个依赖A库的2.0版本，他们都使用了类xxx.xx.Clazz，其实现的逻辑因类库版本的不同而结构完全不同。那么这两个Web程序的其中一个必然因为加载的Clazz不是所使用的Clazz而出现问题！而这对于开发来说是非常致命的！</p><h3 id="tomcat-container设计" tabindex="-1">Tomcat Container设计？ <a class="header-anchor" href="#tomcat-container设计" aria-label="Permalink to &quot;Tomcat Container设计？&quot;">​</a></h3><p>我们看下几个Container之间的关系：</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/538b76e1f6.jpg" alt=""></p><p>从上图上，我们也可以看出Container顶层也是基于Lifecycle的组件设计的。</p><ul><li><strong>在设计Container组件层次组件时，上述4个组件分别做什么的呢？为什么要四种组件呢？</strong></li></ul><p><strong>Engine</strong> - 表示整个catalina的servlet引擎，多数情况下包含<strong>一个或多个</strong>子容器，这些子容器要么是Host，要么是Context实现，或者是其他自定义组。</p><p><strong>Host</strong> - 表示包含多个Context的虚拟主机的。</p><p><strong>Context</strong> — 表示一个ServletContext，表示一个webapp，它通常包含一个或多个wrapper。</p><p><strong>Wrapper</strong> - 表示一个servlet定义的（如果servlet本身实现了SingleThreadModel，则可能支持多个servlet实例）。</p><ul><li><strong>结合整体的框架图中上述组件部分，我们看下包含了什么</strong>？</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/fbb25b5e8d.png" alt=""></p><p>很明显，除了四个组件的嵌套关系，Container中还包含了Realm，Cluster，Listeners, Pipleline等支持组件。</p><p>这一点，还可以通过相关注释可以看出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>**Loader** - Class loader to use for integrating new Java classes for this Container into the JVM in which Catalina is running.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Logger** - Implementation of the log() method signatures of the ServletContext interface.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Manager** - Manager for the pool of Sessions associated with this Container.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Realm** - Read-only interface to a security domain, for authenticating user identities and their corresponding roles.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>**Resources** - JNDI directory context enabling access to static resources, enabling custom linkages to existing server components when Catalina is embedded in a larger server.</span></span></code></pre></div><h3 id="tomcat-lifecycle机制" tabindex="-1">Tomcat LifeCycle机制？ <a class="header-anchor" href="#tomcat-lifecycle机制" aria-label="Permalink to &quot;Tomcat LifeCycle机制？&quot;">​</a></h3><ul><li>Server及其它组件</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/da4124641b.png" alt=""></p><ul><li>Server后续组件生命周期及初始化</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/c32f31a6a9.png" alt=""></p><ul><li>Server的依赖结构</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/9bb09105e6.png" alt=""></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>public interface Lifecycle {</span></span>
<span class="line"><span>    /** 第1类：针对监听器 **/</span></span>
<span class="line"><span>    // 添加监听器</span></span>
<span class="line"><span>    public void addLifecycleListener(LifecycleListener listener);</span></span>
<span class="line"><span>    // 获取所以监听器</span></span>
<span class="line"><span>    public LifecycleListener[] findLifecycleListeners();</span></span>
<span class="line"><span>    // 移除某个监听器</span></span>
<span class="line"><span>    public void removeLifecycleListener(LifecycleListener listener);</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    /** 第2类：针对控制流程 **/</span></span>
<span class="line"><span>    // 初始化方法</span></span>
<span class="line"><span>    public void init() throws LifecycleException;</span></span>
<span class="line"><span>    // 启动方法</span></span>
<span class="line"><span>    public void start() throws LifecycleException;</span></span>
<span class="line"><span>    // 停止方法，和start对应</span></span>
<span class="line"><span>    public void stop() throws LifecycleException;</span></span>
<span class="line"><span>    // 销毁方法，和init对应</span></span>
<span class="line"><span>    public void destroy() throws LifecycleException;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    /** 第3类：针对状态 **/</span></span>
<span class="line"><span>    // 获取生命周期状态</span></span>
<span class="line"><span>    public LifecycleState getState();</span></span>
<span class="line"><span>    // 获取字符串类型的生命周期状态</span></span>
<span class="line"><span>    public String getStateName();</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="tomcat-中executor" tabindex="-1">Tomcat 中Executor? <a class="header-anchor" href="#tomcat-中executor" aria-label="Permalink to &quot;Tomcat 中Executor?&quot;">​</a></h3><ul><li><p>1.Tomcat希望将Executor也纳入Lifecycle<strong>生命周期管理</strong>，所以让它实现了Lifecycle接口</p></li><li><p>2.<strong>引入超时机制</strong>：也就是说当work queue满时，会等待指定的时间，如果超时将抛出RejectedExecutionException，所以这里增加了一个<code>void execute(Runnable command, long timeout, TimeUnit unit)</code>方法; 其实本质上，它构造了JUC中ThreadPoolExecutor，通过它调用ThreadPoolExecutor的<code>void execute(Runnable command, long timeout, TimeUnit unit)</code>方法。</p></li></ul><h3 id="tomcat-中的设计模式" tabindex="-1">Tomcat 中的设计模式？ <a class="header-anchor" href="#tomcat-中的设计模式" aria-label="Permalink to &quot;Tomcat 中的设计模式？&quot;">​</a></h3><ul><li><strong>责任链模式：管道机制</strong></li></ul><p>在软件开发的常接触的责任链模式是FilterChain，它体现在很多软件设计中：</p><ol><li><strong>比如Spring Security框架中</strong></li></ol><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/3ab425a747.jpg" alt=""></p><ol start="2"><li><strong>比如HttpServletRequest处理的过滤器中</strong></li></ol><p>当一个request过来的时候，需要对这个request做一系列的加工，使用责任链模式可以使每个加工组件化，减少耦合。也可以使用在当一个request过来的时候，需要找到合适的加工方式。当一个加工方式不适合这个request的时候，传递到下一个加工方法，该加工方式再尝试对request加工。</p><p>网上找了图，这里我们后文将通过Tomcat请求处理向你阐述。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/aa644df09a.jpg" alt=""></p><ul><li><p><strong>外观模式：request请求</strong></p></li><li><p><strong>观察者模式：事件监听</strong></p></li></ul><p>java中的事件机制的参与者有<strong>3种角色</strong></p><ol><li><code>Event Eource</code>：事件源，发起事件的主体。</li><li><code>Event Object</code>：事件状态对象，传递的信息载体，就好比Watcher的update方法的参数，可以是事件源本身，一般作为参数存在于listerner 的方法之中。</li><li><code>Event Listener</code>：事件监听器，当它监听到event object产生的时候，它就调用相应的方法，进行处理。</li></ol><p>其实还有个东西比较重要：事件环境，在这个环境中，可以添加事件监听器，可以产生事件，可以触发事件监听器。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/25dc0e7e44.png" alt=""></p><ul><li><strong>模板方式： Lifecycle</strong></li></ul><p>LifecycleBase是使用了<strong>状态机</strong>+<strong>模板模式</strong>来实现的。模板方法有下面这几个：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>// 初始化方法</span></span>
<span class="line"><span>protected abstract void initInternal() throws LifecycleException;</span></span>
<span class="line"><span>// 启动方法</span></span>
<span class="line"><span>protected abstract void startInternal() throws LifecycleException;</span></span>
<span class="line"><span>// 停止方法</span></span>
<span class="line"><span>protected abstract void stopInternal() throws LifecycleException;</span></span>
<span class="line"><span>// 销毁方法</span></span>
<span class="line"><span>protected abstract void destroyInternal() throws LifecycleException;</span></span></code></pre></div><hr><blockquote><p>本章整理自 <a href="https://pdai.tech/md/interview/x-interview.html" target="_blank" rel="noreferrer">pdai.tech《Java 全栈知识点问题汇总》</a>，仅作个人复习存档；图片已转存至自建图床，少数原图失效处保留了待补标记。</p></blockquote>`,326)])])}const h=a(p,[["render",t]]);export{u as __pageData,h as default};
